verification_commands.ac1:
set -u
F=docs/criteria/scoring_map/process.md
test -f "$F" || { echo "ac1 RED: $F missing - this card's whole deliverable is this file"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Problem Description[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac1 RED: no '## Problem Description' section - the dimension name is the grading rubric's own words so a grader can find it"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac1 RED: the section carries no '- Claim: N/M' line in the exact record format"; exit 1; }
set -- $CL
[ "$1" -le "$2" ] || { echo "ac1 RED: the claim $1/$2 claims more than its maximum"; exit 1; }
[ "$2" = "2" ] || { echo "ac1 RED: the Problem Description maximum is 2 per the grading rubric, not $2 - do not invent a scale"; exit 1; }
printf "%s\n" "$S" | grep -qE "^- Reason: ..*" || { echo "ac1 RED: no measured Reason line - a claim without a reason is a score invented from nothing"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac1 RED: no single backticked First entry point - the map must give ONE 30-second pointer, not a pile of candidates"; exit 1; }
[ "$(printf "%s\n" "$S" | grep -cE '^- First entry point:')" = "1" ] || { echo "ac1 RED: more than one First entry point line - a map with two front doors is not a map"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac1 RED: the named first entry point '$EP' does not exist on this tree - a pointer to a file that is not there is the exact defect this milestone exists to remove"; exit 1; } ;; esac
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac1 RED: evidence paths that do not exist on this tree:$MISS"; exit 1; }
printf "%s\n" "$S" | grep -qiE "README" || { echo "ac1 RED: the Problem Description record never points at README.md - the rubric grades how README describes problem, functionality and expected behaviour, so README IS the entry surface"; exit 1; }
# The two README surfaces the claim actually rests on must be NAMED, not implied: the
# Features table is where functionality is described and the Online demo section is
# where expected behaviour is shown. A record that points at README.md generically
# sends the grader to the wrong 30 seconds.
printf "%s\n" "$S" | grep -q "Features" || { echo "ac1 RED: the Problem Description record never names the README Features table - that heading is where README describes the functionality half of the rubric clause, so the record has to send the reader there by name"; exit 1; }
printf "%s\n" "$S" | grep -qiE "Online demo" || { echo "ac1 RED: the Problem Description record never names the README Online demo section - expected behaviour is demonstrated there, and it is the section t111 is repairing in this same milestone"; exit 1; }
# the two spec surfaces the reason leans on must exist for the reason to be checkable
test -f product-spec.md || { echo "ac1 RED: product-spec.md is gone from the tree - the Problem Description reason cites a spec that is not there"; exit 1; }
test -f docs/requirements/Chapter1_ProjectOverview.md || { echo "ac1 RED: docs/requirements/Chapter1_ProjectOverview.md is gone - the problem statement this record cites as evidence no longer exists"; exit 1; }
# README must really still carry the structure the record describes
tr -d '\r' < README.md | grep -qE "^## Features[[:space:]]*$" || { echo "ac1 RED: README.md no longer carries a '## Features' level-2 heading - the record describes a README structure that has moved, so the record (not the README) is what has to change"; exit 1; }
tr -d '\r' < README.md | grep -qE "^## Online demo[[:space:]]*$" || { echo "ac1 RED: README.md no longer carries a '## Online demo' level-2 heading - same rule: a record describing a heading that is not there is a stale premise"; exit 1; }
echo "ac1 evidence: README carries '## Features' and '## Online demo' as level-2 headings, product-spec.md and Chapter1_ProjectOverview.md are on the tree"
echo "ac1 GREEN: PROBLEM DESCRIPTION recorded - claim $1/$2 within the rubric maximum, one existing first entry point ($EP), every evidence path resolves, README named as the entry surface with its Features and Online demo surfaces named by name"

verification_commands.ac2:
set -u
F=docs/criteria/scoring_map/process.md
test -f "$F" || { echo "ac2 RED: $F missing"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Product Specification[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac2 RED: no '## Product Specification' section - the rubric names spec + publicly accessible task tracker + evidence agents used it"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac2 RED: no '- Claim: N/M' line in the exact record format"; exit 1; }
set -- $CL
[ "$1" -le "$2" ] && [ "$2" = "2" ] || { echo "ac2 RED: the Product Specification claim '$1/$2' is malformed or does not use the rubric maximum 2"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac2 RED: no single backticked First entry point"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac2 RED: first entry point '$EP' does not exist"; exit 1; } ;; esac
printf "%s\n" "$S" | grep -qiE "issue|tracker" || { echo "ac2 RED: the record never names the task tracker - half the rubric criterion is tracker accessibility with acceptance criteria"; exit 1; }
printf "%s\n" "$S" | grep -qE 'docs/issues/closed' || { echo "ac2 RED: the record does not point at docs/issues/closed - the in-repo card archive is the offline-checkable evidence that every card carried acceptance criteria"; exit 1; }
printf "%s\n" "$S" | grep -qE 'docs/log/orchestrator_wal[.]jsonl|docs/state/merge_history[.]json' || { echo "ac2 RED: the record names no process-evidence artifact - 'agents used the tracker' is evidenced by the WAL and the merge history, and the record must say which"; exit 1; }
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac2 RED: evidence paths that do not exist:$MISS"; exit 1; }
# the counts the record is allowed to cite are counts this fence can re-measure
WALN=$(wc -l < docs/log/orchestrator_wal.jsonl | tr -d " ")
MHN=$(python3 -c "import json;print(len(json.load(open('docs/state/merge_history.json',encoding='utf-8'))['entries']))" 2>/dev/null)
CARDS=$(ls docs/issues/closed/*.md 2>/dev/null | wc -l | tr -d " ")
echo "ac2 evidence: re-measurable process counts WAL lines=$WALN merge_history entries=$MHN closed cards=$CARDS"
[ "${CARDS:-0}" -ge 50 ] || { echo "ac2 RED: only $CARDS closed cards - the archive this record leans on has gone missing, so the claim it supports is unverifiable"; exit 1; }
# The survey recon said the WAL runs 'seq 1..1267'. It does not: the committed file
# carries 229 lines whose seq values run 1040..1269. The record is therefore only
# allowed to cite the highest seq and the line count, and this fence measures both
# rather than trusting the prose.
command -v python3 >/dev/null || { echo "ac2 RED: python3 missing - the WAL seq range cannot be measured"; exit 1; }
WALMAX=$(python3 - <<'PYWAL'
import json
seqs = []
for line in open("docs/log/orchestrator_wal.jsonl", encoding="utf-8", errors="replace"):
    line = line.strip()
    if not line:
        continue
    try:
        seqs.append(int(json.loads(line)["seq"]))
    except Exception:
        pass
print(max(seqs) if seqs else 0)
PYWAL
)
[ "${WALMAX:-0}" -ge 1269 ] || { echo "ac2 RED: the WAL's highest seq is $WALMAX, below the 1269 the groom measured - the process-evidence artifact this claim rests on has been truncated or replaced"; exit 1; }
echo "ac2 evidence: WAL highest seq=$WALMAX (the groom measured 1269; the file carries 229 lines starting at seq 1040, so 'seq 1..N' is NOT a citable claim)"
# A count stated in the record must be a DATE-STAMPED FLOOR, never a bare present-tense
# number: this archive grows as the milestone proceeds, and a record that says "the
# archive holds 110 cards" in present tense goes stale the moment t116 merges. The
# canonical citable form is 'measured 2026-10-23: at least 110 closed cards'.
printf "%s\n" "$S" | grep -qiE '2026-[0-9]{2}-[0-9]{2}' || { echo "ac2 RED: the section states process evidence without a 2026-mm-dd measurement date - an undated count of a growing archive is a claim that cannot survive the milestone it was written in"; exit 1; }
FLOOR=$(printf "%s\n" "$S" | sed -n 's/.*at least \([0-9][0-9]*\) closed cards.*/\1/p' | head -1)
[ -n "$FLOOR" ] || { echo "ac2 RED: the section carries no 'at least <N> closed cards' floor - the archive size is what this claim rests on, so it must be stated as a floor the fences can re-measure rather than as a present-tense count that goes stale mid-milestone"; exit 1; }
[ "$FLOOR" -le "$CARDS" ] || { echo "ac2 RED: the record's floor is $FLOOR closed cards but the tree now measures $CARDS - the floor was stated above the measured evidence, which is an invented number"; exit 1; }
echo "ac2 evidence: the stated floor ($FLOOR closed cards, date-stamped) is at or below the measured $CARDS, so the floor holds as the archive grows"
test -f docs/criteria/req_coverage_verification.md || { echo "ac2 RED: the deep-dive report docs/criteria/req_coverage_verification.md is gone - the requirement-coverage evidence this section points at no longer exists"; exit 1; }
echo "ac2 GREEN: PRODUCT SPECIFICATION recorded - claim $1/$2, one existing first entry point ($EP), the tracker and the in-repo evidence archive named, and the process counts a grader can re-measure ($CARDS closed cards, $MHN merge-history entries, $WALN WAL lines, highest WAL seq $WALMAX)"
